unknown_record_test() ->
    ?assertEqual({error, {unknown_record, not_a_known_record}},
                 beam4pm_ai_contracts_codec:from_map(not_a_known_record, #{})).

missing_field_test() ->
    %% admission_decision requires decision_id; an empty map must
    %% surface the constructor's own missing-field validation unchanged.
    ?assertMatch({error, {missing_field, _}},
                 beam4pm_ai_contracts_codec:from_map(admission_decision, #{})).

invalid_json_test() ->
